bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name")" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
const e=process.env;
const common={host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:4000};
for(const name of ['gaybbs','videobot']){
 const db=new pg.Pool({...common,database:name});
 try{
  const t=await db.query(`SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND (table_name ILIKE '%topic%' OR table_name ILIKE '%pin%' OR table_name ILIKE '%entry%') ORDER BY table_name`);
  process.stdout.write('STK04_DB_'+name.toUpperCase()+'_TABLES='+t.rows.map(x=>x.table_name).join(',')+'\n');
  for(const row of t.rows.filter(x=>['posting_topics','posting_sticker_entry_pins','topic_registry','topics','log_topics','videobot_sticker_entry_pins'].includes(x.table_name))){
   const cols=await db.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position",[row.table_name]);
   process.stdout.write('STK04_DB_'+name.toUpperCase()+'_COLUMNS_'+row.table_name+'='+cols.rows.map(x=>x.column_name).join(',')+'\n');
   const q=await db.query('SELECT COUNT(*)::int AS n FROM '+row.table_name);
   process.stdout.write('STK04_DB_'+name.toUpperCase()+'_COUNT_'+row.table_name+'='+q.rows[0].n+'\n');
  }
 }catch(e){process.stdout.write('STK04_DB_'+name.toUpperCase()+'_QUERY_UNAVAILABLE='+String(e.code||e.message||'UNKNOWN').replace(/[^A-Z0-9_]/g,'').slice(0,45)+'\n');}
 finally{await db.end();}
}
NODE
